import fs from 'fs';
const tj = JSON.parse(fs.readFileSync('<scratch>','utf8'));
export const B='http://192.168.31.145:8799';
export async function call(tool, args={}){
  const r = await fetch(`${B}/api/agent/${tool}`,{method:'POST',headers:{'content-type':'application/json','authorization':'Bearer '+tj.token},body:JSON.stringify(args)});
  const t = await r.text(); let j; try{j=JSON.parse(t)}catch{j=t}
  return {status:r.status, body:j};
}
export function redact(o){return JSON.stringify(o,null,1).split(tj.token).join('<TOKEN>')}
EOF
